  'AUTH_INVALID',
  'AUTH_PERMANENT',
  'TIMEOUT',
  'RATE_LIMIT',
  'PERMISSION',
  'CHANNEL_UNAVAILABLE',
  'CONVERSATION_STATE',
  'NETWORK',
  'CONFIG',
  'GATEWAY',
  'BILLING',
  'OVERLOADED',
  'MODEL_NOT_FOUND',
  'UNKNOWN',
] as const satisfies readonly AppErrorCode[];

/** The component allowed to perform or present the recovery action. */
export type ErrorRecoveryScope = 'app' | 'host' | 'provider';

/** Fixed, non-executable recovery verbs accepted by the host boundary. */
export type ErrorRecoveryActionKind =
  | 'retry'
  | 'reauthenticate'
  | 'reconfigure'
  | 'open-settings'
  | 'contact-support';

/**
 * Bounded targets for a recovery action. These identify a UI or provider
 * destination only; they cannot contain commands, scripts, paths, arguments,
 * URLs, or any other executable payload.
 */
export type ErrorRecoveryTarget =
  | 'authentication'
  | 'conversation'
  | 'model'
  | 'provider'
  | 'settings'
  | 'support';

ex** A declarative recovery instruction understood by the host. */
export type ErrorRecoveryAction = {
  kind: ErrorRecoveryActionKind;
  target?: ErrorRecoveryTarget;
};

export type ErrorRecovery = {
  retryable: boolean;
  scope: ErrorRecoveryScope;
  action?: ErrorRecoveryAction;
};

/**
 * Stable recovery policy for every AppErrorCode. Only errors that can safely
 * repeat the same operation are retryable. UNKNOWN deliberately has no action:
 * the raw error must be exposed to the user rather than presenting a fabricated
 * recovery path.
 */
export const APP_ERROR_RECOVERY: Readonly<Record<AppErrorCode, ErrorRecovery>> = {
  AUTH_INVALID: {
    retryable: false,
    scope: 'host',
    action: { kind: 'reauthenticate', target: 'authentication' },
  },
  AUTH_PERMANENT: {
    retryable: false,
    scope: 'host',
    action: { kind: 'reauthenticate', target: 'authentication' },
  },
  TIMEOUT: {
    retryable: true,
    scope: 'app',
    action: { kind: 'retry' },
  },
  RATE_LIMIT: {
    retryable: true,
    scope: 'app',
    action: { kind: 'retry' },
  },
  PERMISSION: {
    retryable: false,
    scope: 'host',
    action: { kind: 'contact-support', target: 'support' },
  },
  CHANNEL_UNAVAILABLE: {
    retryable: true,
    scope: 'host',
    action: { kind: 'retry' },
  },
  CONVERSATION_STATE: {
    retryable: false,
    scope: 'app',
    action: { kind: 'reconfigure', target: 'conversation' },
  },
  NETWORK: {
    retryable: true,
    scope: 'app',
    action: { kind: 'retry' },
  },
  CONFIG: {
    retryable: false,
    scope: 'host',
    action: { kind: 'reconfigure', target: 'settings' },
  },
  GATEWAY: {
    retryable: true,
    scope: 'provider',
    action: { kind: 'retry' },
  },
  BILLING: {
    retryable: false,
    scope: 'host',
    action: { kind: 'open-settings', target: 'settings' },
  },
  OVERLOADED: {
